  function discOf(text,base){
    var t=String(text==null?'':text).trim();if(!t)return 0;
    var v=t.slice(-1)==='%'?base*num(t.slice(0,-1))/100:num(t);
    return Math.max(0,Math.min(base,r2(v)));
  }
