  // ---------- ส่งออก Excel (CSV) ตามรายการที่กรองอยู่ ----------
  $('lvExport').addEventListener('click',function(){
    var key=LS.key,cols=COLS[key],rows=filtered(key);
    function q(v){v=String(v==null?'':v);return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;}
    var val={date:function(x){return thDate(x.date);},no:function(x){return x.no;},st:function(x){return x.stText;},by:function(x){return x.by;},cus:function(x){return x.cus;},pcode:function(x){return x.cusCode;},
      ref:function(x){return x.ref;},kids:function(x){return x.kids.map(function(k){return k.no;}).join(' ');},total:function(x){return x.total.toFixed(2);},
      refAmt:function(x){return x.use?x.use.used.toFixed(2)+' / '+x.use.total.toFixed(2):'';},refSt:function(x){return x.use?USE_T[x.use.st]:'';},
      kidAmt:function(x){var u=x.down;if(!u)return '';return u.multi?u.multi.map(function(m){return m.lab+' '+m.cum.toFixed(2)+' / '+m.total.toFixed(2);}).join(' ; '):u.cum.toFixed(2)+' / '+u.total.toFixed(2);},
      kidSt:function(x){var u=x.down;if(!u)return '';return u.multi?u.multi.map(function(m){return m.lab+' '+USE_T[m.st];}).join(' ; '):USE_T[u.st];}};
    var csv=[cols.map(function(c){return q(c[1]);}).join(',')].concat(rows.map(function(x){return cols.map(function(c){return q(val[c[0]](x));}).join(',');})).join('\r\n');
    try{var a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'}));a.download=CFG[key].prefix+'_list.csv';document.body.appendChild(a);a.click();a.remove();
      toast('ส่งออก '+rows.length+' รายการแล้ว');}catch(err){toast('เบราว์เซอร์นี้ไม่อนุญาตให้ดาวน์โหลดไฟล์',true);}
  });
