  // ---------- แบบฟอร์มพิมพ์ ----------
  function bahtText(n){
    var NUM=['ศูนย์','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'],POS=['','สิบ','ร้อย','พัน','หมื่น','แสน'];
    function grp(x){ // x < 1,000,000
      var s='',str=String(x),len=str.length;
      for(var i=0;i<len;i++){var d=+str[i],p=len-i-1;if(d===0)continue;
        if(p===0&&d===1&&len>1)s+='เอ็ด';else if(p===1&&d===2)s+='ยี่';else if(!(p===1&&d===1))s+=NUM[d];
        s+=POS[p];}
      return s;
    }
    function words(x){if(x===0)return '';var s='';var m=Math.floor(x/1000000),r=x%1000000;if(m>0)s+=words(m)+'ล้าน';return s+grp(r);}
    n=Math.round(n*100)/100;var b=Math.floor(n),st=Math.round((n-b)*100);
    if(b===0&&st===0)return 'ศูนย์บาทถ้วน';
    return (b>0?words(b)+'บาท':'')+(st>0?words(st)+'สตางค์':'ถ้วน');
  }
