  // ======================================================================================
  // ================= ใบรับเงิน (Spec RV-02 รับชำระเงินอื่น ๆ · Spec ฟิลด์ v2 19 ต.ค. 2026) =================
  // แสดง: branch payer_businesspartner taxinvoice_txno vat_type credit_term duedate post_remark
  //   ยอด: netamount_before_vat(55) arap_vat(56) vat_amount(57) netamount_after_vat(58) witholdingtax_amount(60) payment_medium_amount(40) outstanding(42)
  //   รายการ: material amount netamount_before_vat vat_value (อัตราตามกลุ่มสินค้าใน Master data) vat_amount netamount_after_vat remark
  //   ตัดออกตาม BA 19 ต.ค.: stx_type (ระบบเติมตามลูกค้าตามใบกำกับภาษี) · ข้อมูลภายใน unpaid_amount pay_amount flow_refdocno (ระบบยังเก็บ)
  //                         arap_netamount_after_vat(37) prepaid_amount(41) (ระบบยังคำนวณ)
  //   แถบย่อย: รับชำระโดย (178–192) · v2 ตัดออกจากหน้าจอ: หัก ณ ที่จ่าย ใบกำกับภาษีขาย รายการลงบัญชี post_remark (ระบบสร้างหลังบ้าน)
//   v2: อัตราภาษีหัก ณ ที่จ่ายกรอกที่สรุปยอด · vat_type / vat_businesspartner รายบรรทัด ระบบเติมจากหัวเอกสาร
  // Spec v2 ตัดออก: ยอดแถว 38,39,43,45–55,59 · แถบลดหนี้ (161–170) เงินมัดจำ (210–223) ชำระล่วงหน้า (241–254) หักหนี้เอกสาร AR (293–303)
  // อ้างอิงได้ 3 แบบ: ค้นหาใบจอง (รับตามงวด/มัดจำ/ยอดใบจอง) · ค้นหาใบส่งสินค้า · ไม่อ้างอิง (กรอกรายการเอง)
  // ======================================================================================
  // รายการรับชำระ (Material_Detail.material อ้างอิง material) — ประเภทการรับชำระ + สินค้า
  // rate = อัตราภาษีตามการตั้งค่ากลุ่มสินค้าใน Master data (mock)
  var RV_MAT=[{code:'PAY-INST',name:'ค่างวดตามสัญญา',rate:7},{code:'PAY-DEP',name:'เงินมัดจำ',rate:7},{code:'PAY-ADV',name:'เงินรับล่วงหน้า',rate:0},
              {code:'PAY-GOODS',name:'ค่าสินค้าตามใบจอง',rate:7},{code:'PAY-SVC',name:'ค่าบริการ',rate:7},{code:'PAY-OTH',name:'รับชำระอื่น ๆ',rate:0}];
  var GROUP_VAT={'รถยนต์':7,'อุปกรณ์':7,'บริการ':7};   // Master data กลุ่มสินค้า › อัตราภาษี (mock)
  function matRate(code){var m=RV_MAT.filter(function(x){return x.code===code;})[0];if(m)return m.rate;var p=prodBy(code);return p&&GROUP_VAT[p.group]!=null?GROUP_VAT[p.group]:7;}
  function rvMatName(code){var m=RV_MAT.filter(function(x){return x.code===code;})[0];if(m)return m.name;var p=prodBy(code);return p?p.name:(code||'');}
  var rvMatOptions='<option value="">— เลือกรายการ —</option><optgroup label="ประเภทการรับชำระ">'+RV_MAT.map(function(m){return '<option value="'+m.code+'">'+esc(m.name)+'</option>';}).join('')+'</optgroup>'+
    productOptions.replace('<option value="">— เลือกสินค้า —</option>','');
  // รับชำระโดย (receivemethod อ้างอิง Master data วิธีรับชำระเงิน) · acc = บัญชีตัวอย่างสำหรับรายการลงบัญชี
  var RECV=[{v:'cash',t:'เงินสด',acc:'1111 เงินสด'},{v:'transfer',t:'เงินโอน',acc:'1112 เงินฝากธนาคาร'},{v:'cheque',t:'เช็ค',acc:'1113 เช็ครับ'},{v:'card',t:'บัตรเครดิต',acc:'1114 ลูกหนี้บัตรเครดิต'}];
  var CHQ_TYPE=[['PO','Payee Only'],['CPO','Cheque and Cash'],['CO','Cheque and CO'],['CSH','Cash']];   // ตัวเลือกตาม Spec แถว 180
