  function soRecv(o){
    var p=o.pay||{},out=[];
    if(PAYCFG[p.type]){
      var mat={schedule:'PAY-INST',deposit:'PAY-DEP',prepaid:'PAY-ADV'}[p.type];
      p.rows.forEach(function(x,i){var left=r2(x.gross-(x.paid||0));if(left>0.004)out.push({key:i,mat:mat,label:(p.type==='schedule'?'งวดที่ '+(i+1):PAYCFG[p.type].title.replace('ชำระ',''))+' · ครบกำหนด '+thDate(x.due),amt:left,rate:x.rate});});
    }else{var left=r2((o.res?o.res.S.g:0)-(o.paidAll||0));if(left>0.004)out.push({key:'all',mat:'PAY-GOODS',label:'ค่าสินค้าตามใบจอง',amt:left,rate:o.vat==='exempt'?0:7});}
    return out;
  }
