  // คำนวณรายการรับชำระ: amt = มูลค่าตามรูปแบบภาษี · rate = อัตราภาษีของบรรทัด (7 / 0)
  function calcRv(items,mode){
    var S={a:0,b:0,v:0,g:0,u:0};
    var L=items.map(function(it){
      var a=r2(it.amt||0),rt=(it.rate==null?7:it.rate)/100,b,v;
      if(!it.code){a=0;}
      if(mode==='include'){b=r2(a/(1+rt));v=r2(a-b);}else if(mode==='exempt'){b=a;v=0;}else{b=a;v=r2(a*rt);}
      var g=r2(b+v);S.a+=a;S.b+=b;S.v+=v;S.g+=g;S.u+=(it.unpaid!=null?it.unpaid:0);
      return {a:a,b:b,v:v,g:g};
    });
    Object.keys(S).forEach(function(k){S[k]=r2(S[k]);});
    return {L:L,S:S};
  }
